# Locate any script that contains a pip install command
python3 - << 'PYEOF'
import os, pathlib, re, sys
t = pathlib.Path(os.environ["TARGET_DIR"])
matches = []
for root, dirs, files in os.walk(t):
    for f in files:
        if f.endswith('.sh') or f.endswith('.bash'):
            p = pathlib.Path(root) / f
            try:
                txt = p.read_text()
            except Exception:
                continue
            if re.search(r'pip\s+install', txt):
                rel = p.relative_to(t)
                matches.append(str(rel))
if matches:
    print("Scripts containing pip install:")
    for m in matches:
        print(m)
else:
    print("No shell scripts with pip install found.")
